using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Cosmos DB indexing is managed via the container's indexing policy, not EF Core.
        // HasIndex was removed — it now throws InvalidOperationException in EF Core 9.

        modelBuilder.Entity<Blog>(b =>
        {
            // Preserve "Discriminator" property name (EF Core 9 defaults to "$type")
            b.HasDiscriminator<string>("Discriminator");

            // Preserve "Blog|{key}" id format (EF Core 9 defaults to key-only)
            b.HasRootDiscriminatorInJsonId(true);
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

